L000352		\section{Some useful properties and definitions}
L000353	Before addressing the specific proofs discussed in the main text, we first remind some definitions and properties of Bargmann functions and Majorana polynomials.
L000354	
L000355	Let's consider a CV monomode quantum state $\ket{\psi}$ and its expansion in Fock states $\ket{k}$:
L000356	\[
L000357	\ket{\psi} = \sum_{k=0}^{\infty} c_k\ket{k};
L000358	\]
L000359	its associated Bargmann function $B_{\ket{\psi}}(z)$ is defined as:
L000360	\[
L000361	B_{\ket{\psi}}(z) = \sum_{k=0}^{\infty} c_k\frac{z^k}{\sqrt{k!}}.
L000362	\]
L000363	We recall that  the coefficients $c_k$ can be recovered from the Bargmann function as follow:
L000364	\beq
L000365	\label{eq:ckB}
L000366	c_k = \frac{1}{\pi}\int_{\mathbb{C}} B_{\ket{\psi}}(z) \frac{(z^*)^k}{\sqrt{k!}}e^{-\abs{z}^2}d^2z.
L000367	\eeq
L000368	
L000369	
L000370	The Bargmann function is normalized as
L000371	\beq
L000372	\label{eq:normBargmann}
L000373	\frac{1}{\pi} \int_{\mathbb{C}}
L000374	\abs{B_{\ket{\psi}}(z)}^2 e^{-\abs{z}^2} d^2z =
L000375	\sum_{k=0}^{\infty}\abs{c_k}^2 = 1.
L000376	\eeq
L000377	
L000378	To the minimal $N$-photon SSRC pure state  $\ket{\psi}_s = \sum_{k=0}^{N}  c_k\ket{k}_a\ket{N-k}_b$, we can associate the Majorana polynomial:
L000379	\beq
L000380	\label{eq:majorPoly}
L000381	P_N(z) =  \sum_{k=0}^N c_k\binom{N}{k}^{1/2}z^k
L000382	\eeq
L000383	and the coefficients $c_k$ can be obtained from the Majorana polynomials as follows:
L000384	\[
L000385	c_k =  \frac{N+1}{\pi}\int_{\mathbb{C}} P_{N}(z)\binom{N}{k}^{1/2}(z^*)^k \left(1+\abs{z}^2\right)^{-(N+2)} d^2z.
L000386	\]
L000387	Some identities will be useful.
L000388	\subsubsection{Incomplete gamma function}
L000389	The following relations hold~\cite{abramowitz_64}
L000390	\begin{align}
L000391		\label{eq:gammaidentities}
L000392		2\int_0^x r^{2k+1}e^{-r^2}dr & = \int_0^{x^2} u^k e^{-u} du \\
L000393		\frac{1}{k!}\int_{0}^x u^k e^{-u}du	&= 1 -\left(1+x+\frac{x^2}{2!} + \frac{x^3}{3!} + \cdots +  \frac{x^k}{k!} \right) e^{-x}
L000394	\end{align}
L000395	\subsubsection{Majoration of the truncated exponential sum}
L000396	For all positive real $x$  and integer $k\geq 2$ such that $\frac{x}{k} >1$, we have the following upper bound
L000397	\beq
L000398	\label{eq:majorationTruncExp}
L000399	\sum_{m=0}^{k} \frac{x^m}{m!} \leq \frac{x^k}{k!}
L000400	\left[
L000401	1 + \frac{1}{\frac{x}{k} -1}
L000402	\right].
L000403	\eeq
L000404	It  can be obtained as follows:
L000405	\[
L000406	\sum_{m=0}^{k} \frac{x^m}{m!}
L000407	= \left(\frac{x^k}{k!}\right)\left[
L000408	1 +  \sum_{m=0}^{k-1} k(k-1)\cdots (m+1) x^{m-k}
L000409	\right]
L000410	\]
L000411	but $k(k-1)\cdots (m+1) \leq k^{k-m}$ hence
L000412	\[
L000413	\sum_{m=0}^{k} \frac{x^m}{m!} \leq
L000414	\frac{x^k}{k!}\left[
L000415	1 +  \sum_{m=0}^{k-1} \left(\frac{x}{k}\right)^{m-k}
L000416	\right] =
L000417	\frac{x^k}{k!}\left[
L000418	1 +  \left(\frac{k}{x}\right)^k\sum_{m=0}^{k-1} \left(\frac{x}{k}\right)^{m}
L000419	\right]
L000420	\]
L000421	the geometric sum can be calculated explicitly:
L000422	\[
L000423	\sum_{m=0}^{k-1} \left(\frac{x}{k}\right)^{m} = \frac{\left(\frac{x}{k}\right)^k-1}{\frac{x}{k} -1} \leq \frac{\left(\frac{x}{k}\right)^k}{\frac{x}{k} -1}
L000424	\]
L000425	where we have supposed that $x > k$.
L000426	Finally, we obtain
L000427	\[
L000428	\sum_{m=0}^{k} \frac{x^m}{m!} \leq \frac{x^k}{k!}
L000429	\left[
L000430	1 + \frac{1}{\frac{x}{k} -1}
L000431	\right].
L000432	\]
L000433	\subsubsection{Binomial coefficients}
L000434	We have the following results
L000435	\begin{align}
L000436		\label{eq:binomargt}
L000437		\binom{N}{k}\frac{k!}{N^k} &= \left(1-\frac{1}{N}\right)\left(1-\frac{2}{N}\right)\left(1-\frac{3}{N}\right)\cdots \left(1-\frac{k-1}{N}\right) \leq 1; \; 0\leq k \leq N  \\
L000438		\label{eq:BinomApprox}
L000439		& = 1 - \frac{k(k-1)}{2N} + \mathcal{O}(\frac{k^3}{N^2}).\\
L000440		\label{eq:BinomJoseMaj}
L000441		\ln \left( \binom{N}{k} \frac{k!}{N^k} \right) &\leq N [ -1 + x(1 - \ln ( x )) ]; \forall k\geq 2
L000442	\end{align}
L000443	where we set $x = 1 - (k-1)/N$ to simplify notations.
L000444	The upper bound of the logarithm can be obtained as follows.
L000445	Take the logarithm of Eq.~\eqref{eq:binomargt}
L000446	and use the fact that $t \mapsto \ln(1-t)$ is decreasing, then :
L000447	\begin{align*}
L000448		\ln \left( \binom{N}{k} \frac{k!}{N^{k}} \right) &= \sum_{j=1}^{k-1} \ln \left( 1 - \frac{j}{N} \right)\\
L000449		&\leq \int_{0}^{k-1} \ln \left( 1 - \frac{t}{N} \right) dt\\
L000450		&= N \int_{1 - (k-1)/N}^1 \ln(u) du\\
L000451		&= N [u\ln u - u]_{x}^1\\
L000452		&= N(-1 - x\ln(x) + x)\\
L000453		&= N(-1 + x(1 - \ln(x))).
L000454	\end{align*}
