L000457	\section{Necessary condition for normalization}
L000458	
L000459	We will show in this section the reciprocal of what was shown in the main article: If a Majorana polynomial is normalized with a Gaussian measure, then it can always be arbitrarily well approached by a truncated polynomial of degree $K \ll \sqrt{N}$ on a given region. For this we define the following integral
L000460	\beq
L000461	\label{eq:INR}
L000462	I(N,R) =  \frac{1}{\pi}\int_{\abs{z}\leq R}\abs{P_N\left(\frac{z}{\sqrt{N}}\right)}^2e^{-\abs{z}^2} dz_rdz_i
L000463	\eeq
L000464	where
L000465	$P_N(z)$ is the Majorana polynomial of order $N$, given by Eq.~\eqref{eq:majorPoly},    associated to some state specified by its coefficients $c_k$ ($k=0,1,\cdots, N$), satisfying $\sum_{k=0}^N\abs{c_k}^2=1$.
L000466	
L000467	\subsection{Part 1: Controlling the coefficients}
L000468	
L000469	Let $I_{\mathbb{C}}(N) \equiv \lim_{R \rightarrow \infty} I(N,R)$.
L000470	We'll show that if $\lim_{N\rightarrow \infty} I_{\mathbb{C}}(N) = 1$, then we get the following
L000471	\be\label{sta} \forall \varepsilon > 0, \forall \delta > 0, \exists N_0, \forall N \geq N_0, \exists K < \delta\sqrt{N}, \sum_{k=K+1}^N |c_{k,N}|^2 \leq \varepsilon, \ee
L000472	where we indexed the coefficients of $P_N$ as $c_{k,N}$. Statement \eqref{sta} indeed corresponds to what is claimed in the main text: $K \ll \sqrt{N}$.\newline
L000473	Fix $\varepsilon > 0$, we will explicitly construct these $K$. For all $N \geq 0$ let
L000474	$K(N)$ be the smallest index such that
L000475	\[ \sum_{k=K(N)+1}^N |c_{k,N}|^2 \leq \varepsilon. \]
L000476	Being the smallest, we also get
L000477	\[ \sum_{k=K(N)}^N |c_{k,N}|^2 > \varepsilon. \]
L000478	
L000479	We now show that for all $\delta > 0$, there exists $N_0$ such that for all $N \geq N_0$,
L000480	$K(N) < \delta \sqrt{N}$.\newline
L000481	We will show that by contradiction. So, we assume that for a certain $\delta > 0$ and for all $N_0$, there exists $N \geq N_0$
L000482	such that $K(N) \geq \delta \sqrt{N}$, and we would like to show that in this case $I_{\mathbb{C}}(N)$ can not converge to 1.
L000483	Note that $\delta$ is a constant independant of $N$.\newline
L000484	To simplify the notation, in the following we replace $K(N)$ with $K$. We then write :
L000485	\begin{align*}
L000486	    I_{\mathbb{C}}(N) &= \sum_{k=0}^N |c_{k,N}|^2 \binom{N}{k}\frac{k!}{N^k}\\
L000487	    &= \sum_{k=0}^{K-1} |c_{k,N}|^2 \binom{N}{k}\frac{k!}{N^k} + \sum_{k=K}^N |c_{k,N}|^2 \binom{N}{k}\frac{k!}{N^k}\\
L000488	    &= H(K, N) + T(K, N).
L000489	\end{align*}
L000490	
