L000528	\subsection{Part 2: Truncating the polynomial}
L000529	We will show that for $N$, and $K \ll N$ such that
L000530	\[ \sum_{k=K}^N |c_k|^2 \leq \varepsilon, \]
L000531	there exists $0 < R' < \sqrt{N}$ such that for $|z| \leq R'$
L000532	\[ \left| P_N \left( \frac{z}{\sqrt{N}} \right) - P_{N,K} \left( \frac{z}{\sqrt{N}} \right) \right|^2 \leq \varepsilon. \]
L000533	Notice that $R'$ is not necessarily the same as $R$, used in the integral \eqref{eq:INR}. We first use Cauchy-Schwarz for $|z| \leq R'$ where $R'$ is any positive radius for now :
L000534	\begin{align*}
L000535	    \left| P_N \left( \frac{z}{\sqrt{N}} \right) - P_{N,K} \left( \frac{z}{\sqrt{N}} \right) \right|^2
