L000698	   \left|P_N\left(\frac{z}{\sqrt{N}}\right)-B\left(z\right)\right|^2 &=\left| \sum_{k=0}^K \frac{c_kz^k}{\sqrt{k!}}\left(1-\left(\frac{\binom{N}{k}k!}{N^k} \right)^{1/2}\right)\right|^2\\
L000699	   &\leq (K+1) \sum_{k=0}^K \frac{|c_kz^k|^2}{{k!}}\left|1-\left(\frac{\binom{N}{k}k!}{N^k} \right)^{1/2}\right|^2\\
L000700	\end{align*}
