L000793	             &= \sqrt{\sum_{k=K+1}^\infty   \frac{\left|z\right|^{2k}}{k!} }   \cdot \sqrt{\sum_{k=K+1}^\infty \left|c_k\right|^2}\\
L000794			\end{align*}
L000795	        First term is the rest of the exponential serie, and can be smaller than $\epsilon$ for sufficiently large $K$ at fixed $R$, while second term is also infinitesimal due to the two hypothesis.
L000796		\end{itemize}
L000797	\end{itemize}
L000798	
L000799	Altogether, the three terms appearing in there can be made arbitrarily small, hence proving the uniform convergence for states in the CV limit.
L000800	\end{proof}
L000801	
L000802	
L000803	
L000804	\subsection{Convergence of Majorana zeros towards Bargmann zeros}
L000805	In this section, we study the convergence of the Majorana polynomial to the Bargmann function in the CV limit, through the zeros of the respective functions. For a fixed $n <N$, consider $\ket{\psi}_{S } =\sum_{k=0}^{n} c_k \ket{k}_a\ket{N-k}_b$ and $\ket{\psi}_{C} = \sum_{k=0}^{n} c_k \ket{k}$. The SSRC (CV) state can be parametrized by the set of rotations $\{\alpha_k\}$ (displacements $\{\beta_k\}$) as follows:
L000806		\begin{equation}\label{s_eq}
L000807			\ket{\psi}_{S} =\sum_{k=0}^{n} c_k \ket{k}_a\ket{N-k}_b= \mathcal{N}\prod_{k=1}^{n} R(\alpha_k,N)\hat{a}^\dagger R^\dagger(\alpha_k, N) \cdot (\hat{b}^\dagger)^{N-n} \ket{\emptyset}
L000808		\end{equation}
L000809		\begin{equation}\label{CV general}
L000810			\ket{\psi}_{C} = \sum_{k=0}^{n} c_k \ket{k} = \frac{c_n}{\sqrt{n!}}\prod_{k=1}^{n} D(\beta_k)\hat{a}^\dagger D^\dagger(\beta_k)  \ket{\emptyset}
L000811		\end{equation}
L000812	The set $\{\alpha_k\}$ is the set of zeros of the truncated Majorana polynomial $P_{n,N}\left(\frac{z}{\sqrt{N}}\right)$ associated to $\ket{\psi}_{S}$, $P_{n,N}\left(\frac{z}{\sqrt{N}}\right)= \sum_{k=0}^n\frac{c_k\binom{N}{k}^{1/2}}{N^{k/2}}z^k$. Similarly, the set $\{\beta_k\}$ is the set of zeros associated to the truncated Bargmann function $B_n(z)=\sum_{k=0}^n \frac{c_k}{\sqrt{k!}}z^k $. For $n \ll N$ the coefficients become asymptotically close implying an asymptotic equality between the sets $\{\alpha_k\}$ and $\{\beta_k\}$.
L000813	
L000814	First, consider the following example:  we will prove that zeros of Majorana polynomial of $c_0\ket{0}\ket{N} + c_1\ket{1}\ket{N-1}+ c_2\ket{2}\ket{N-2}$ become asymptotically close for $N\gg1$ to the zeros of the Bargmann function of $c_0\ket{0} + c_1\ket{1}+ c_2\ket{2}$.
L000815	\begin{proof}
L000816	On the CV side, the state $\ket{\psi}_C = c_0\ket{0}+c_1\ket{1} +c_2\ket{2}$ can be rewritten as $\ket{\psi}_C =  \frac{c_2}{\sqrt{2}}(a^\dagger-\beta_1^*)(a^\dagger-\beta_0^*)\ket{\emptyset}$. Coefficients $\beta_{0,1}$ are related to the coefficients $c_k$ by identification of the coefficients along the Fock basis. It gives:
L000817		\begin{equation}\label{identification}
L000818			c_0  =\frac{c_2}{\sqrt{2}}\beta_1^*\beta_0^* \quad \text{and } \quad c_1=-\frac{c_2}{\sqrt{2}}(\beta_1^*+\beta_0^*)
L000819		\end{equation}
L000820		The two sets of solutions, $(\beta_{0,-},\beta_{1-}) $ and $(\beta_{0,+},\beta_{1+}) $, yield two states : $\ket{\psi_-}_C = \frac{c_2}{\sqrt{2}}(a^\dagger-\beta_{1-}^*)(a^\dagger-\beta_{0-}^*)\ket{\emptyset}$ and $\ket{\psi_+}_C = \frac{c_2}{\sqrt{2}}(a^\dagger-\beta_{1+}^*)(a^\dagger-\beta_{0+}^*)\ket{\emptyset}$, that are equal as one checks that $(\beta_{0-},\beta_{1-})  = (\beta_{1+},\beta_{0+}) $. The set of equations between $\{c_k\}$ and $\{\beta_k\}$ is non linear, yielding multiple solutions. However, those are simply permutations, translating the underlying commutation relation : $(a^\dagger-\beta_1^*)(a^\dagger-\beta_0^*) = (a^\dagger-\beta_0^*)(a^\dagger-\beta_1^*)$.\\
L000821	
L000822	 On the SSRC side, state $\ket{\psi}_S = c_0\ket{0}\ket{N} + c_1\ket{1}\ket{N-1}+ c_2\ket{2}\ket{N-2}$ can be rewritten as
L000823	 \be
L000824	 \ket{\psi}_S= \mathcal{N}^{-1} R(\alpha_0, N )\hat{a}^\dagger R^\dagger(\alpha_0, N ) R(\alpha_1, N )\hat{a}^\dagger R^\dagger(\alpha_1, N ) (\hat{b}^\dagger)^{N-2}\ket{\emptyset}.
L000825	 \ee
L000826	Expanding and identifying the terms in the SSRC basis relates $\{c_k\}$ and $\{\alpha_k\}$. It gives
L000827		\begin{align}
L000828			c_0  &=\frac{c_2}{\sqrt{2}}\alpha_1^*\alpha_0^* \left(1-\frac{(|\alpha_0|^2+ |\alpha_1|^2+1)}{2N}+\mathcal{O}(\frac{1}{N^2}) \right)\\
L000829	        c_1&=-\frac{c_2}{\sqrt{2}}\left(\alpha_1^*+\alpha_0^* -\frac{\alpha_0^*(1+|\alpha_0|^2)+\alpha_1^*(1+|\alpha_1|^2)}{2N}+\mathcal{O}(\frac{1}{N^2})\right)
L000830		\end{align}
L000831	
L000832	which coincides with Eq. \ref{identification} in the limit $|\alpha_k|/N\ll1, 1\ll N $, hence yielding the same set of zeros.
L000833	\end{proof}
L000834	
L000835	Let's now treat the general case described above, and prove that asymptotically, the two sets of zeros $\{\alpha_k\}_k, \{\beta_k\}_k$ coincide.
L000836	
L000837	\begin{proof}
L000838	
L000839	
L000840		\textbf{a)} Identifying both sides of Eq. \ref{CV general} along $\ket{k}$ yields the following relation between $\{\beta_k\}$ and $\{c_k\}$, where $\mathcal{P}_{n-k}([1,n])$ denote the set of all subset of $\{ 1, ...n \} $ of size $n-k$:
L000841	
L000842		\begin{align}\label{c_k function of beta_k}
L000843			\forall k\in [0,n] ,  \frac{c_k}{\sqrt{k!}}=\frac{c_n}{\sqrt{n!}}(-1)^{n-k}\sum_{I\in\mathcal{P}_{n-k}([1,n]) }\prod_{i\in I}\beta^*_i
L000844		\end{align}
L000845		\textbf{ b)} Identifying both sides of Eq. \ref{s_eq} along $\ket{k}_a\ket{N-k}_b$ yields the following relation between $\{\alpha_k\}$ and $\{c_k\}$:
L000846	    \begin{align*}
L000847			\forall k\in [0,n],   \frac{c_k}{\sqrt{k!}}=\frac{c_n}{\sqrt{n!}}(-1)^{n-k}\sum_{I\in\mathcal{P}_{n-k}([1,n]) }\prod_{l\in I}\alpha^*_l\left(1-\frac{|\alpha_l|^2}{N}\right)^{-1/2}\frac{\sqrt{(N-k)!}}{\sqrt{(N-n)!}\sqrt{N}^{n-k}}
L000848		\end{align*}
L000849	
L000850		In this set of equations, $\frac{\sqrt{(N-k)!}}{\sqrt{(N-n)!}\sqrt{N}^{n-k}} \sim 1 $ for $N\gg k,n$, and $\prod_{l\in I}\alpha^*_l\left(1-\frac{|\alpha_l|^2}{N}\right)^{-1/2}= \prod_{l\in I}\alpha^*_l + \mathcal{O}(1/N)$, assuming that $\alpha_l$ are of order 1, independent of N, i.e. that $\max_l(|\alpha_l|)\ll N $. Assuming this hypothesis fulfilled, one gets the simplified set of equations :
L000851		\begin{align} \label{c_k function of alpha_k}
L000852			\forall k\in [0, n],  \frac{c_k}{\sqrt{k!}}=\frac{c_n}{\sqrt{n!}}(-1)^{n-k}\sum_{I\in\mathcal{P}_{n-k}([1,n]) }\prod_{l\in I}\alpha^*_l + \mathcal{O}(1/N)
L000853		\end{align}
L000854	
L000855		In \textbf{ b)}, the set of the $n$ parameters $\{\alpha_k\}$ is solution of the set of $n+1 $  equations given by Eqs. \ref{c_k function of alpha_k}. In \textbf{ a)},the set of the $n$ parameters $\{\beta_k\}$ is solution of the set of $n+1 $ equations given by Eqs. \ref{c_k function of beta_k}. Neglecting the $\mathcal{O}(1/N)$, Eqs. \ref{c_k function of alpha_k}  and \ref{c_k function of beta_k} form the same set of non linear-equations, and the parameters $\{\alpha_k\}$  and  $\{\beta_k\}$ are two solutions.  A priori, it is possible that  those are different solutions, ie $\{\alpha_k\} \neq \{\beta_k\}$. However, a state is described uniquely by the unordered set of zeros. The set of equations must yield one solution plus all possible permutation of it. This implies that the sets of parameters  $\{\alpha_k\}$  and  $\{\beta_k\}$ coincides well, $\{\alpha_k\}=\{\beta_k\}$.
L000856	\end{proof}
